head.b:skin:
:root{color-scheme:dark;--bg:#0b0b10;--panel:#12131b;--panel2:#191a25;--ink:#f8f8fb;--muted:#a9adbd;--line:rgba(255,255,255,.12);--violet:#6c4de6;--violet2:#8a72ff;--teal:#9ff0e5;--shadow:0 28px 80px #0005;--font:Inter,system-ui,-apple-system,"Segoe UI",sans-serif;--display:"DM Sans",Inter,system-ui,sans-serif}
:root[data-theme="light"]{color-scheme:light;--bg:#f3f5f9;--panel:#fff;--panel2:#f8f9fc;--ink:#171823;--muted:#5e6373;--line:rgba(25,27,45,.13);--shadow:0 24px 65px #1f213a18}
*{box-sizing:border-box}html{scroll-behavior:smooth;-webkit-text-size-adjust:100%;scroll-padding-top:88px}body{margin:0;background:var(--bg);color:var(--ink);font:400 15px/1.65 var(--font);overflow-x:hidden}a{color:inherit;text-decoration:none}button,input{font:inherit}button{cursor:pointer}button:focus-visible,a:focus-visible,input:focus-visible{outline:2px solid var(--teal);outline-offset:4px}.wrap{width:min(1280px,calc(100% - 48px));margin-inline:auto}
.topline{height:31px;border-bottom:1px solid var(--line);color:var(--muted);font-size:10px}.topline .wrap{height:100%;display:flex;align-items:center;justify-content:space-between;gap:12px}.topline strong{color:var(--ink);letter-spacing:.15em}.status{display:flex;align-items:center;gap:8px}.dot{width:6px;height:6px;border-radius:50%;background:var(--teal);box-shadow:0 0 12px var(--teal)}
.header{position:sticky;top:0;z-index:80;background:color-mix(in srgb,var(--bg) 82%,transparent);backdrop-filter:blur(18px);border-bottom:1px solid var(--line)}.nav{min-height:76px;display:flex;align-items:center;gap:24px}.brand{display:inline-flex;align-items:center;gap:10px;white-space:nowrap;font:750 22px/1 var(--display);letter-spacing:-.065em}.brand-mark{width:39px;height:39px;display:grid;place-items:center;border:1px solid #ffffff3b;border-radius:13px;background:linear-gradient(145deg,#7756ee,#4831aa 63%,#168e91);color:white;box-shadow:0 8px 28px #6844d744;position:relative}.brand-word em{font-style:normal;color:var(--teal)}.nav-links{display:flex;align-items:center;gap:clamp(12px,1.8vw,24px);margin-inline:auto}.nav-links a{color:var(--muted);font-size:12px;font-weight:600;white-space:nowrap}.nav-links a:hover{color:var(--ink)}.nav-actions{display:flex;align-items:center;gap:8px}.btn{display:inline-flex;align-items:center;justify-content:center;gap:9px;min-height:43px;padding:0 17px;border:1px solid transparent;border-radius:999px;white-space:nowrap;font-size:12px;font-weight:750;transition:transform .22s,background .22s,border-color .22s}.btn:hover{transform:translateY(-2px)}.btn-primary{color:#fff;background:linear-gradient(112deg,#4d19b1,#6f5adc);box-shadow:0 10px 32px #6d4ee13b}.btn-primary:hover{background:linear-gradient(112deg,#6332ca,#8878ef)}.btn-ghost{color:var(--ink);background:#ffffff08;border-color:var(--line);backdrop-filter:blur(12px)}.btn-ghost:hover{background:#ffffff12}.icon-btn,.burger{display:grid;place-items:center;width:40px;height:40px;border:1px solid var(--line);border-radius:50%;background:var(--panel);color:var(--ink);font-size:15px}.burger{display:none;font-size:19px}.menu{display:none;position:absolute;top:calc(100% + 8px);inset-inline:16px;padding:10px;border:1px solid var(--line);border-radius:19px;background:var(--panel);box-shadow:var(--shadow);z-index:100}.menu.open{display:grid;animation:menuIn .22s ease both}.menu a{padding:13px 14px;border-radius:12px;font-size:14px}.menu a:hover{background:#805bff19}@keyframes menuIn{from{opacity:0;transform:translateY(-7px)}to{opacity:1;transform:none}}
.hero{position:relative;isolation:isolate;overflow:hidden;min-height:min(700px,calc(100svh - 108px));display:flex;align-items:center;padding:60px 0 68px;border-bottom:1px solid var(--line);background:radial-gradient(ellipse at 78% 46%,#6342d51b,transparent 42%),var(--bg)}.hero:before{content:"";position:absolute;inset:0;z-index:-2;opacity:.17;background-image:linear-gradient(#ffffff11 1px,transparent 1px),linear-gradient(90deg,#ffffff11 1px,transparent 1px);background-size:44px 44px;mask-image:linear-gradient(90deg,transparent,#000 42%)}.hero-grid{display:grid;grid-template-columns:minmax(0,1.03fr) minmax(360px,.97fr);align-items:center;gap:clamp(28px,4vw,64px)}.hero-copy{position:relative;z-index:5;max-width:650px}.eyebrow{display:inline-flex;align-items:center;gap:9px;padding:7px 11px;border:1px solid #9ff0e533;border-radius:999px;background:#9ff0e50c;color:var(--teal);font-size:10px;font-weight:850;letter-spacing:.12em;text-transform:uppercase}.hero h1{margin:24px 0 18px;font:500 clamp(43px,5.25vw,76px)/1.03 var(--display);letter-spacing:-.075em}.hero h1 .line{display:block;white-space:nowrap;background:linear-gradient(105deg,var(--ink) 8%,color-mix(in srgb,var(--ink) 78%,#9290b7) 82%);-webkit-background-clip:text;background-clip:text;color:transparent}.hero h1 em{font-style:normal;background:linear-gradient(110deg,#9ff0e5,#9aa3ff);-webkit-background-clip:text;background-clip:text;color:transparent}.hero-lede{max-width:540px;margin:0;color:var(--muted);font-size:clamp(14px,1.2vw,16px);line-height:1.9}.hero-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:25px}.hero-proof{display:flex;flex-wrap:wrap;gap:12px 18px;margin-top:18px;color:var(--muted);font-size:11px}.hero-proof span:before{content:"✓";margin-inline-end:7px;color:var(--teal)}
.art{position:relative;min-width:0;aspect-ratio:1;max-width:590px;width:100%;margin-inline:auto;display:grid;place-items:center;isolation:isolate}.art-glow{position:absolute;inset:6%;border-radius:50%;background:radial-gradient(circle,#7654ef30,#36c7c112 40%,transparent 72%);filter:blur(18px);animation:glow 7s ease-in-out infinite alternate}.orbit{position:absolute;inset:7%;border:1px solid #ffffff19;border-radius:50%;transform:rotate(-18deg) scaleY(.7);box-shadow:0 0 70px #6348e714,inset 0 0 50px #ffffff04}.orbit:before,.orbit:after{content:"";position:absolute;width:7px;height:7px;border-radius:50%;background:var(--teal);box-shadow:0 0 18px #9ff0e5d9}.orbit:before{left:18%;top:14%}.orbit:after{right:10%;bottom:17%;background:#a48cff}.core{position:absolute;inset:18%;border-radius:50%;background:radial-gradient(circle at 36% 28%,#b9b0ff33,transparent 38%),linear-gradient(145deg,#ffffff0c,#ffffff02);border:1px solid #ffffff1b;box-shadow:inset 0 1px #ffffff12,0 24px 90px #0003;backdrop-filter:blur(8px);mask-image:radial-gradient(ellipse,#000 46%,#000a 66%,transparent 77%)}.slab{position:absolute;z-index:2;width:66%;height:19%;left:17%;top:22%;border:1px solid #ffffff2c;border-radius:17px;background:linear-gradient(115deg,#ffffff18,#ffffff04);box-shadow:0 18px 55px #0003,inset 0 1px #ffffff22;backdrop-filter:blur(10px);transform:rotate(-12deg) skewX(-5deg);animation:slabFloat 8s ease-in-out infinite}.slab:nth-of-type(5){top:38%;left:21%;width:61%;animation-delay:-2.5s;background:linear-gradient(115deg,#6c4de633,#ffffff07)}.slab:nth-of-type(6){top:53%;left:25%;width:57%;animation-delay:-5s;background:linear-gradient(115deg,#20a99f24,#ffffff05)}.slab-grid{position:absolute;inset:13px;border-radius:10px;opacity:.75;background-image:radial-gradient(circle,#9ff0e5d9 1px,transparent 1.5px);background-size:17px 17px;mask-image:linear-gradient(90deg,transparent,#000 12%,#000 80%,transparent)}.slab-wave{position:absolute;left:5%;right:5%;top:50%;height:35%;border-top:1px solid #9ff0e5b3;border-radius:50%;transform:rotate(-4deg);box-shadow:0 -5px 20px #68e7e021}.art-label{position:absolute;right:1%;top:14%;z-index:4;padding:9px 12px;border:1px solid var(--line);border-radius:12px;background:color-mix(in srgb,var(--panel) 70%,transparent);color:var(--teal);font-size:9px;font-weight:850;letter-spacing:.13em}.glass-card{position:absolute;z-index:5;width:min(235px,48%);padding:15px 16px;border:1px solid #ffffff29;border-radius:16px;background:color-mix(in srgb,var(--panel) 82%,transparent);box-shadow:0 18px 45px #0003,inset 0 1px #ffffff0c;backdrop-filter:blur(16px)}.glass-card.top{left:0;top:18%}.glass-card.bottom{right:-1%;bottom:13%}.glass-kicker{color:var(--teal);font-size:9px;font-weight:850;letter-spacing:.12em}.glass-title{margin-top:6px;color:var(--ink);font:650 15px/1.35 var(--display)}.glass-meta{margin-top:5px;color:var(--muted);font-size:10px}.symbol{display:inline-grid;place-items:center;width:27px;height:27px;margin-bottom:8px;border-radius:9px;background:#9ff0e51a;color:var(--teal);font-size:14px}
@keyframes glow{from{transform:scale(.94);opacity:.72}to{transform:scale(1.07);opacity:1}}@keyframes slabFloat{0%,100%{transform:translateY(0) rotate(-12deg) skewX(-5deg)}50%{transform:translateY(-9px) rotate(-10deg) skewX(-5deg)}}@keyframes pillIn{from{opacity:0;transform:translateY(14px) scale(.98)}to{opacity:1;transform:translateY(0) scale(1)}}@keyframes lineIn{from{opacity:0;transform:translateY(105%)}to{opacity:1;transform:translateY(0)}}@keyframes riseIn{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}html.anim.go .header .brand,html.anim.go .nav-links a,html.anim.go .nav-actions>*{animation:riseIn .55s cubic-bezier(.16,1,.3,1) both}html.anim.go .nav-links a:nth-child(2){animation-delay:.04s}html.anim.go .nav-links a:nth-child(3){animation-delay:.08s}html.anim.go .nav-links a:nth-child(4){animation-delay:.12s}html.anim.go .nav-links a:nth-child(5){animation-delay:.16s}html.anim.go .hero .eyebrow{animation:riseIn .6s cubic-bezier(.16,1,.3,1) .12s both}html.anim.go .hero .line span{animation:lineIn .75s cubic-bezier(.16,1,.3,1) both}html.anim.go .hero .line:nth-child(2) span{animation-delay:.12s}html.anim.go .hero .line:nth-child(3) span{animation-delay:.24s}html.anim.go .hero-lede{animation:riseIn .65s cubic-bezier(.16,1,.3,1) .36s both}html.anim.go .hero .btn-primary{animation:pillIn .65s cubic-bezier(.16,1,.3,1) .48s both}html.anim.go .hero .btn-ghost{animation:pillIn .65s cubic-bezier(.16,1,.3,1) .62s both}html.anim.go .hero-proof{animation:riseIn .6s cubic-bezier(.16,1,.3,1) .74s both}html.anim.go .art .slab{animation-name:slabFloat}html.anim.go .glass-card{animation:riseIn .7s cubic-bezier(.16,1,.3,1) .72s both}html.anim.go .section-head{animation:riseIn .6s cubic-bezier(.16,1,.3,1) .5s both}
:root[data-theme="light"] .hero:before{opacity:.09;background-image:linear-gradient(#15172a12 1px,transparent 1px),linear-gradient(90deg,#15172a12 1px,transparent 1px)}:root[data-theme="light"] .slab{border-color:#28253a24;background:linear-gradient(115deg,#fff9,#ffffff4a);box-shadow:0 18px 55px #5e56741c,inset 0 1px #fff}:root[data-theme="light"] .glass-card{border-color:#34334b26;background:#ffffffd9;box-shadow:0 18px 45px #3b3d581c,inset 0 1px #fff}
.section{padding:66px 0}.section-head{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:24px}.section-kicker{color:var(--teal);font-size:10px;font-weight:850;letter-spacing:.17em}.section h2{margin:8px 0 5px;font:550 clamp(28px,3vw,42px)/1.15 var(--display);letter-spacing:-.06em}.section-head p{margin:0;color:var(--muted);font-size:13px}.count-pill{display:inline-flex;align-items:center;gap:8px;padding:8px 12px;border:1px solid var(--line);border-radius:999px;color:var(--muted);font-size:11px;white-space:nowrap}.count-pill strong{color:var(--ink)}.searchbar{display:flex;gap:8px;max-width:650px;margin:0 0 20px;padding:6px;border:1px solid var(--line);border-radius:16px;background:var(--panel);box-shadow:inset 0 1px #ffffff06,0 18px 45px #0000000a}.searchbar input{width:100%;min-width:0;padding:10px 13px;border:0;outline:0;color:var(--ink);background:transparent;font-size:13px}.searchbar input::placeholder{color:var(--muted)}.searchbar button{flex:0 0 auto;border:0;border-radius:11px;padding:0 17px;background:var(--ink);color:var(--bg);font-size:12px;font-weight:800}.searchbar button:hover{background:var(--teal)}.categories{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 22px}.ur-category{padding:9px 13px;border:1px solid var(--line);border-radius:999px;background:transparent;color:var(--muted);font-size:11px;font-weight:750}.ur-category:hover,.ur-category.active{background:#805bff20;border-color:#9b82ff6b;color:var(--ink)}.ur-tool-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:13px}.ur-card{position:relative;display:flex;flex-direction:column;min-width:0;min-height:216px;padding:20px;border:1px solid var(--line);border-radius:19px;background:linear-gradient(145deg,#ffffff08,#ffffff02);box-shadow:inset 0 1px #ffffff06;transition:transform .28s,border-color .25s,background .25s;overflow:hidden}.ur-card:before{content:"";position:absolute;inset-inline:0;top:0;height:1px;background:linear-gradient(90deg,transparent,#9ff0e55c,transparent);opacity:0;transition:opacity .25s}.ur-card:hover{transform:translateY(-5px);border-color:#9ff0e548;background:linear-gradient(145deg,#9ff0e50d,#805bff0a);box-shadow:0 22px 55px #00000020}.ur-card:hover:before{opacity:1}.ur-card[hidden]{display:none}.ur-card-top{display:flex;align-items:center;justify-content:space-between;gap:10px}.ur-icon{display:grid;place-items:center;min-width:43px;width:43px;height:43px;border:1px solid var(--line);border-radius:14px;background:linear-gradient(145deg,#805bff25,#9ff0e50c);color:var(--violet2);font:700 14px var(--display)}.ur-tag{padding:5px 8px;border:1px solid var(--line);border-radius:999px;background:#ffffff05;color:var(--muted);font-size:9px;font-weight:850;letter-spacing:.06em}.ur-card h3{margin:16px 0 5px;color:var(--ink);font:650 17px/1.35 var(--display)}.ur-card p{margin:0;color:var(--muted);font-size:12px;line-height:1.75}.ur-card-foot{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:auto;padding-top:20px;color:var(--teal);font-size:11px;font-weight:800}.ur-card-foot small{color:var(--muted);font-size:9px;font-weight:550}.empty{padding:32px;border:1px dashed var(--line);border-radius:18px;color:var(--muted);text-align:center}.empty[hidden]{display:none}.ad-note{margin:26px 0;padding:20px;border:1px solid var(--line);border-radius:18px;background:var(--panel);color:var(--muted);font-size:12px}
.page-shell{min-height:60vh;padding:38px 0 70px}.page-shell .main{max-width:960px;margin:auto}.page-shell .widget{padding:24px;border:1px solid var(--line);border-radius:20px;background:var(--panel)}.page-shell .post-title,.page-shell h1{font:650 clamp(28px,4vw,42px)/1.2 var(--display);letter-spacing:-.045em}.page-shell .post-body{color:var(--ink);line-height:1.9;overflow-wrap:anywhere}.page-shell .post-body a{color:var(--teal);text-decoration:underline}.footer{border-top:1px solid var(--line);padding:32px 0 20px}.footer-grid{display:flex;justify-content:space-between;gap:30px;flex-wrap:wrap}.footer-copy{max-width:430px;color:var(--muted);font-size:12px}.footer-links{display:flex;gap:12px 18px;flex-wrap:wrap}.footer-links a{color:var(--muted);font-size:11px}.footer-links a:hover{color:var(--teal)}.copyright{margin-top:25px;padding-top:16px;border-top:1px solid var(--line);color:var(--muted);font-size:10px;display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}
@media(max-width:1160px){.nav-links,.nav-actions .btn{display:none}.burger{display:grid}.nav{min-height:68px}.hero{min-height:unset;padding:48px 0 56px}.hero-grid{grid-template-columns:minmax(0,1fr) minmax(300px,.88fr);gap:18px}.hero h1{font-size:clamp(38px,5.2vw,64px)}.ur-tool-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:720px){.wrap{width:calc(100% - 32px)}.topline .status{display:none}.nav{min-height:64px;gap:10px}.brand{font-size:20px}.brand-mark{width:35px;height:35px}.nav-actions{margin-inline-start:auto}.hero{padding:35px 0 40px}.hero-grid{grid-template-columns:1fr;gap:14px}.hero-copy{text-align:center}.hero h1{font-size:clamp(39px,10.5vw,60px);margin:20px 0 15px}.hero h1 .line{white-space:normal}.hero-lede{margin:auto;font-size:14px}.hero-actions,.hero-proof{justify-content:center}.art{width:min(100%,460px);margin-top:0}.glass-card{width:min(210px,47%);padding:12px}.glass-title{font-size:13px}.glass-card.top{left:0;top:15%}.glass-card.bottom{right:0;bottom:10%}.art-label{right:0;top:11%}.section{padding:46px 0}.section-head{align-items:start;flex-direction:column}.count-pill{align-self:start}.ur-tool-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.ur-card{padding:14px;min-height:210px;border-radius:16px}.ur-card h3{font-size:14px;margin-top:13px}.ur-card p{font-size:11px}.ur-card-foot{font-size:10px;flex-wrap:wrap;padding-top:15px}.ur-card-foot small{display:none}.page-shell .widget{padding:17px}.footer-grid{display:grid;grid-template-columns:1fr}}@media(max-width:380px){.wrap{width:calc(100% - 26px)}.ur-tool-grid{grid-template-columns:1fr}.ur-card{min-height:185px}.hero h1{font-size:39px}.art{margin-inline:-5px;width:calc(100% + 10px)}.glass-card{width:46%}}@media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;animation:none!important;transition:none!important}.art-glow,.slab{animation:none!important}}

body.script:
(function(){var root=document.documentElement;if(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;root.classList.add('anim');var bootTimer=0,started=false,cleaned=false,safety=0;function clean(){if(cleaned)return;cleaned=true;clearTimeout(safety);root.removeEventListener('animationend',onEnd,true);root.classList.remove('anim','go')}function onEnd(e){if(e.animationName==='pillIn'&&e.target.classList.contains('btn-ghost'))clean()}function start(){if(started||cleaned)return;started=true;clearTimeout(bootTimer);root.addEventListener('animationend',onEnd,true);safety=setTimeout(clean,2600);root.classList.add('go')}function boot(){bootTimer=setTimeout(start,900);if(document.fonts&&document.fonts.ready&&typeof document.fonts.ready.then==='function')document.fonts.ready.then(start,start);else start()}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot()})();
(function(){var burger=document.getElementById('burger'),menu=document.getElementById('menu');if(!burger||!menu)return;function set(open){menu.classList.toggle('open',open);burger.setAttribute('aria-expanded',String(open));burger.setAttribute('aria-label',open?'Close menu':'Open menu');burger.textContent=open?'×':'☰'}burger.addEventListener('click',function(e){e.stopPropagation();set(!menu.classList.contains('open'))});menu.addEventListener('click',function(e){if(e.target.closest('a'))set(false)});document.addEventListener('click',function(e){if(menu.classList.contains('open')&&!menu.contains(e.target)&&!burger.contains(e.target))set(false)});document.addEventListener('keydown',function(e){if(e.key==='Escape'&&menu.classList.contains('open')){set(false);burger.focus()}})})();
(function(){var root=document.documentElement,cards=Array.from(document.querySelectorAll('#ur-tool-grid .ur-card')),cats=document.getElementById('to-categories'),input=document.getElementById('to-search'),form=document.getElementById('to-search-form'),empty=document.getElementById('to-empty'),count=document.getElementById('to-result-count'),live=document.getElementById('to-live-count'),langBtn=document.getElementById('ur-language'),themeBtn=document.getElementById('ur-theme'),language='ar',active='All',query='';try{language=localStorage.getItem('utilityra-language')||'ar'}catch(e){}function tr(ar,en){return language==='ar'?ar:en}function norm(v){return String(v||'').toLocaleLowerCase(language==='ar'?'ar':'en').normalize('NFKC')}function label(cat){if(cat==='All')return tr('كل الأدوات','All tools');var c=cards.find(x=>x.dataset.cat===cat);return c&&language==='ar'?(c.dataset.arCat||cat):cat}function renderCats(){if(!cats)return;cats.textContent='';['All',...new Set(cards.map(c=>c.dataset.cat).filter(Boolean))].forEach(cat=>{var b=document.createElement('button');b.type='button';b.className='ur-category'+(cat===active?' active':'');b.textContent=label(cat);b.setAttribute('aria-pressed',String(cat===active));b.addEventListener('click',function(){active=cat;renderCats();filter()});cats.appendChild(b)})}function filter(){var n=0;cards.forEach(c=>{var ok=(active==='All'||c.dataset.cat===active)&&(!query||norm((c.dataset.search||'')+' '+c.textContent+' '+c.dataset.id).includes(norm(query)));c.hidden=!ok;if(ok)n++});if(empty)empty.hidden=n>0;if(count)count.textContent=String(n);if(live)live.textContent=tr('عرض '+n+' من '+cards.length+' أداة','Showing '+n+' of '+cards.length+' tools')}function lang(v){language=v==='en'?'en':'ar';root.lang=language;root.dir=language==='ar'?'rtl':'ltr';document.querySelectorAll('[data-en],[data-ar]').forEach(el=>{var val=el.getAttribute('data-'+language);if(val!==null)el.textContent=val});document.querySelectorAll('[data-en-placeholder],[data-ar-placeholder]').forEach(el=>{var val=el.getAttribute('data-'+language+'-placeholder');if(val!==null)el.placeholder=val});if(input)input.placeholder=tr('ابحث عن أداة: PDF، كلمات، درجات، JSON…','Search tools: PDF, text, grades, JSON…');if(langBtn)langBtn.textContent=tr('EN','عربي');try{localStorage.setItem('utilityra-language',language)}catch(e){}renderCats();filter()}if(langBtn)langBtn.addEventListener('click',()=>lang(language==='ar'?'en':'ar'));var theme='dark';try{theme=localStorage.getItem('utilityra-theme')||'dark'}catch(e){}function setTheme(v){theme=v==='light'?'light':'dark';root.dataset.theme=theme;if(themeBtn){themeBtn.textContent=theme==='dark'?'☼':'◐';themeBtn.setAttribute('aria-label',theme==='dark'?'Switch to light mode':'Switch to dark mode')}try{localStorage.setItem('utilityra-theme',theme)}catch(e){}}if(themeBtn)themeBtn.addEventListener('click',()=>setTheme(theme==='dark'?'light':'dark'));setTheme(theme);if(input)input.addEventListener('input',()=>{query=input.value.trim();filter()});function track(type,tool,term){var base=window.UTILITYRA_API_BASE||'';if(!base)return;var params=new URLSearchParams(location.search),exclude=false;try{exclude=localStorage.getItem('utilityra-owner-exclude')==='1'||localStorage.getItem('utilityra-review-mode')==='1'}catch(e){}if(exclude||params.has('utilityra_review')||params.has('review')||params.has('ai_review')||navigator.webdriver||/bot|crawler|spider|headless|lighthouse|pagespeed/i.test(navigator.userAgent)||location.pathname.startsWith('/admin'))return;var key='';try{key=localStorage.getItem('utilityra-visitor-key')||'';if(!/^[a-zA-Z0-9-]{16,80}$/.test(key)){key=crypto.randomUUID?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(24))).map(x=>x.toString(16).padStart(2,'0')).join('');localStorage.setItem('utilityra-visitor-key',key)}}catch(e){return}fetch(base.replace(/\/$/,'')+'/api/analytics/event',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({visitorKey:key,eventType:type,path:location.pathname,referrer:document.referrer,toolKey:tool||'',searchTerm:term||'',reviewMode:false}),keepalive:true}).catch(()=>{})}if(form)form.addEventListener('submit',function(e){e.preventDefault();query=input?input.value.trim():'';filter();track(cards.some(c=>!c.hidden)?'search':'search_miss','',query);document.getElementById('tools')?.scrollIntoView({behavior:window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})});cards.forEach(c=>{var a=c.querySelector('.ur-card-foot');if(a)a.addEventListener('click',()=>track('tool_open',c.dataset.id,''))});if(cards.length)track('page_view','','');lang(language)})();
